INSERT INTO knowledge_entries (id, user_id, title, content, created_at) VALUES
(1, 1, 'Солнце и его структура',
INSERT INTO knowledge_chunks (entry_id, chunk_index, content, embedding, created_at) VALUES
                                                                                         (1, 0, 'Солнце — звезда спектрального класса G2V. Оно состоит из ядра, где происходят термоядерные реакции, преобразующие водород в гелий.', NULL, NOW()),
                                                                                         (1, 1, 'Энергия Солнца переносится через радиационную зону, где фотоны многократно поглощаются и переизлучаются.', NULL, NOW()),
                                                                                         (1, 2, 'Во внешних слоях Солнца находится конвективная зона, где энергия переносится потоками плазмы.', NULL, NOW()),
                                                                                         (1, 3, 'Внешняя атмосфера Солнца включает фотосферу, хромосферу и корону, которая видна во время затмений.', NULL, NOW()),
                                                                                         (1, 4, 'Если коротко: Солнце — обычная звезда главной последовательности, но именно она определяет условия жизни на Земле.', NULL, NOW()),
                                                                                         (2, 0, 'Звезды формируются в плотных молекулярных облаках под действием гравитационного сжатия.', NULL, NOW()),
                                                                                         (2, 1, 'На стадии протозвезды объект начинает излучать энергию из-за гравитационного коллапса.', NULL, NOW()),
                                                                                         (2, 2, 'Звезды главной последовательности поддерживают термоядерный баланс между давлением и гравитацией.', NULL, NOW()),
                                                                                         (2, 3, 'Конечная эволюция звезды зависит от массы: возможны белый карлик, нейтронная звезда или черная дыра.', NULL, NOW()),
                                                                                         (2, 4, 'Этапы эволюции обычно описывают так: облако газа → протозвезда → главная последовательность → гигант/сверхгигант → компактный остаток.', NULL, NOW()),
                                                                                         (2, 5, 'Почему звезды стареют по-разному? Потому что масса задает скорость расхода топлива и сценарий финальной стадии.', NULL, NOW()),
                                                                                         (3, 0, 'Планеты земной группы включают Меркурий, Венеру, Землю и Марс и имеют каменистую поверхность.', NULL, NOW()),
                                                                                         (3, 1, 'Эти планеты отличаются высокой плотностью и наличием металлического ядра.', NULL, NOW()),
                                                                                         (3, 2, 'Планеты земного типа имеют тонкую или отсутствующую атмосферу по сравнению с газовыми гигантами.', NULL, NOW()),
                                                                                         (4, 0, 'Юпитер и Сатурн относятся к газовым гигантам, состоящим преимущественно из водорода и гелия.', NULL, NOW()),
                                                                                         (4, 1, 'Уран и Нептун классифицируются как ледяные гиганты, содержащие аммиак, метан и воду в различных состояниях.', NULL, NOW()),
                                                                                         (4, 2, 'Атмосферы гигантских планет характеризуются мощными ветрами и сложной динамикой.', NULL, NOW()),
                                                                                         (5, 0, 'Экзопланеты обнаруживаются методом транзита, когда планета проходит перед звездой и уменьшает её яркость.', NULL, NOW()),
                                                                                         (5, 1, 'Метод радиальных скоростей фиксирует колебания звезды из-за гравитационного влияния планеты.', NULL, NOW()),
                                                                                         (5, 2, 'Прямое наблюдение экзопланет возможно только для крупных объектов, находящихся далеко от яркой звезды.', NULL, NOW()),
                                                                                         (5, 3, 'Большинство известных экзопланет обнаружены косвенными методами, а не прямым изображением.', NULL, NOW()),
                                                                                         (6, 0, 'Телескопы бывают оптические, инфракрасные и радиотелескопы, каждый из которых изучает разные диапазоны излучения.', NULL, NOW()),
                                                                                         (6, 1, 'Космические телескопы размещаются за пределами атмосферы Земли для устранения искажений.', NULL, NOW()),
                                                                                         (6, 2, 'Радиотелескопы позволяют наблюдать холодные объекты, такие как газовые облака и реликтовое излучение.', NULL, NOW()),
                                                                                         (6, 3, 'Инфракрасные телескопы позволяют изучать пылевые облака, скрытые от оптических приборов.', NULL, NOW()),
                                                                                         (7, 0, 'Звезда — это горячий шар плазмы, который светит благодаря термоядерному синтезу в ядре.', NULL, NOW()),
                                                                                         (7, 1, 'Энциклопедически: звезда — гравитационно связанный плазменный объект, поддерживающий гидростатическое равновесие.', NULL, NOW()),
                                                                                         (7, 2, 'Простыми словами, звезда — это «космический реактор», где водород постепенно превращается в гелий.', NULL, NOW()),
                                                                                         (7, 3, 'Что отличает звезду от планеты? Звезда сама излучает энергию, а планета в основном отражает чужой свет.', NULL, NOW()),
                                                                                         (8, 0, 'Спектральные классы звезд идут от самых горячих к более холодным: O, B, A, F, G, K, M.', NULL, NOW()),
                                                                                         (8, 1, 'У звезд класса O температура очень высокая, у класса M — заметно ниже, поэтому их цвет и спектр различаются.', NULL, NOW()),
                                                                                         (8, 2, 'По размеру и светимости выделяют карликов, гигантов и сверхгигантов: это разные состояния звездной структуры.', NULL, NOW()),
                                                                                         (8, 3, 'Какие бывают звезды по типу? Часто спрашивают про красные карлики, желтые карлики, красные гиганты и белые карлики.', NULL, NOW()),
                                                                                         (9, 0, 'Масса звезды определяет почти всё: светимость, температуру, продолжительность жизни и финал эволюции.', NULL, NOW()),
                                                                                         (9, 1, 'Маломассивные звезды горят медленнее и живут дольше, а массивные — ярче, горячее и эволюционируют быстрее.', NULL, NOW()),
                                                                                         (9, 2, 'После стадии красного гиганта звезда малой и средней массы сбрасывает оболочку и становится белым карликом.', NULL, NOW()),
                                                                                         (9, 3, 'Если масса очень большая, после коллапса ядра возможны сверхновая, нейтронная звезда или черная дыра.', NULL, NOW()),
                                                                                         (10, 0, 'Солнце — пример звезды главной последовательности и относится к спектральному классу G2V.', NULL, NOW()),
                                                                                         (10, 1, 'Красные гиганты — это звезды поздней стадии, у которых внешние слои сильно расширяются.', NULL, NOW()),
                                                                                         (10, 2, 'Белый карлик — компактный остаток звезды, где уже не идет активный термоядерный синтез водорода.', NULL, NOW()),
                                                                                         (10, 3, 'Пример разговорного запроса: «Солнце — это обычная звезда или особенная?» Ответ: типичная звезда своего класса.', NULL, NOW());
