INSERT INTO messages (conversation_id, role, content, created_at) VALUES
(1, 'USER', 'Привет! Что такое экзопланета?', NOW()),
(1, 'ASSISTANT', 'Экзопланета — это планета, которая обращается вокруг звезды вне Солнечной системы.', NOW()),
(2, 'USER', 'Какими методами обнаруживают экзопланеты?', NOW()),
(2, 'ASSISTANT', 'Основные методы: транзитный, радиальных скоростей и прямое наблюдение.', NOW());
